INSERT INTO declarations (affaire_id, personne_id, faite_le, lieu_id, creneau, garant_id, texte) VALUES (2, 18, '2026-01-09 06:00:00', 9, tstzrange('2026-01-08 18:00:00', '2026-01-08 20:00:00'), NULL, 'J''étais seul·e au Parking Saint-Roch, personne ne peut le confirmer. Oui, je suis passé·e au Théâtre des Ombres dans l''après-midi. Et alors ?');
