-- Les compteurs repartent après les id écrits.
DO $$ BEGIN
  PERFORM setval(pg_get_serial_sequence('lieux', 'id'), (SELECT max(id) FROM lieux));
  PERFORM setval(pg_get_serial_sequence('personnes', 'id'), (SELECT max(id) FROM personnes));
